from django.db.models import Sum
from django.utils import timezone


def conciliar(apps, schema_editor):
    """El stock que existía antes del libro de movimientos (o cargado directo en el campo) queda
    registrado como un ajuste explícito, para que stock y libro reconcilien. No cambia el stock."""
    Elemento = apps.get_model("herramientas", "Elemento")
    Mov = apps.get_model("herramientas", "MovimientoPanol")
    libro = dict(Mov.objects.values_list("elemento").annotate(t=Sum("cantidad")))
    for el in Elemento.objects.all():
        diferencia = el.stock - (libro.get(el.id) or 0)
        if diferencia:
            Mov.objects.create(elemento_id=el.id, tipo="ajuste", cantidad=diferencia, fecha=timezone.localdate(),
                               motivo="Conciliación al migrar: saldo previo sin movimiento en el libro",
                               responsable="migración")



